const r=await tools.exec_command({cmd:"python3 -c 'import re,collections
for p in ("/private/tmp/ehl-mail-control-final.log","/private/tmp/ehl-mail-early-final.log"):
 s=open(p).read(); s=s[s.rfind("===== run summary ====="):]; total=collections.defaultdict(lambda:[0,0,0,0]); events=[]
 for l in s.splitlines():
  m=re.match(r"\[\s*([0-9.]+)s\]\s+(\S+)\s+(\S+)\b",l)
  if not m:continue
  t,w,k=m.groups()
  if w.startswith("mail:mail") and k in ("done","stopped"):
   for i,n in enumerate(("requests","input_tokens","cached_tokens","output_tokens")):
    z=re.search(n+r"=([0-9]+)",l)
    if z:total["mail"][i]+=int(z.group(1))
  if w.startswith("mail:mail") and k=="mail_kind":events.append((float(t),"last_mail"))
  if w in ("verify","orchestrator","result") and k=="done":events.append((float(t),w))
 print(p.split("/")[-1],"mail_usage",total["mail"],"phases",[e for e in events if e[1]!="last_mail"]+([max((e for e in events if e[1]=="last_mail"),default=None)]))'","max_output_tokens":1000});text(r.output);

