"""Optional model-directed analysis of a selected, inert page snapshot.

The workspace uses a separate context in an already supplied browser. It has no
site cookies, is offline, and never receives a live Page or Playwright handle.
It persists JavaScript `state` across a worker's cells; each cell receives a
fresh DOMParser document for the element the model selected.
"""
import asyncio
import os

from extract import locate
from pydantic import TypeAdapter
from pydantic_ai import ModelRetry, RunContext

from browser_tools import Deps, unseen_values

MAX_SNAPSHOT = 250_000
MAX_OUTPUT = 4_000
MAX_FINAL = 20_000
MAX_CODE = 10_000
MAX_CELLS = 8
CELL_SECONDS = 3
SNAPSHOT_SECONDS = 10

SNAPSHOT_JS = r"""
el => {
  const root = el.cloneNode(true);
  const original = [el, ...el.querySelectorAll('*')];
  const copies = [root, ...root.querySelectorAll('*')];
  const blocked = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'META', 'LINK']);
  const attributes = new Set(['aria-label', 'alt', 'title', 'datetime', 'role',
    'placeholder', 'type', 'value', 'checked', 'selected', 'colspan', 'rowspan', 'data-ar']);
  for (let i = 0; i < original.length; i++) {
    const src = original[i], dst = copies[i];
    if (blocked.has(src.tagName) || src.hidden || src.inert ||
        src.getAttribute('aria-hidden') === 'true' ||
        (src.tagName === 'INPUT' && src.type === 'password') ||
        getComputedStyle(src).display === 'none' ||
        getComputedStyle(src).visibility === 'hidden') {
      dst.remove();
      continue;
    }
    for (const attr of [...dst.attributes]) {
      if (!attributes.has(attr.name))
        dst.removeAttribute(attr.name);
    }
    if (src.tagName === 'INPUT' && src.type !== 'password') dst.setAttribute('value', src.value);
    if (src.tagName === 'TEXTAREA') dst.textContent = src.value;
  }
  return {html: root.outerHTML, text: root.textContent || ''};
}
"""

CELL_JS = r"""
async ({html, code}) => {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const lines = [];
  const write = (...items) => lines.push(items.map(x =>
    typeof x === 'string' ? x : JSON.stringify(x)).join(' '));
  const output = {log: write, error: write, warn: write};
  try {
    const fn = new (async function(){}).constructor('doc', 'state', 'console', code);
    const result = await fn(doc, window.__codeState, output);
    if (result !== undefined) write(result);
  } catch (error) {
    write(`${error.name}: ${error.message}`);
  }
  return lines.join('\n');
}
"""

CELL_JSON_JS = r"""
async ({html, code}) => {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const fn = new (async function(){}).constructor('doc', 'state', 'console', code);
  const silent = {log() {}, error() {}, warn() {}};
  const result = await fn(doc, window.__codeState, silent);
  return JSON.stringify(result) || '';
}
"""


class CodeKernel:
    def __init__(self, browser):
        self.browser = browser
        self.context = None
        self.page = None
        self.lock = asyncio.Lock()
        self.cells = 0
        self.finishes = 0

    async def _run(self, html: str, code: str, script: str, limit: int) -> str:
        async with self.lock:
            if len(code) > MAX_CODE:
                raise ValueError(f'Code is {len(code)} characters; limit is {MAX_CODE}.')
            if self.cells >= MAX_CELLS:
                raise ValueError(f'Workspace reached its {MAX_CELLS}-cell limit.')
            if self.page is None:
                self.context = await self.browser.new_context(offline=True)
                await self.context.route('**/*', lambda route: route.abort())
                await self.context.route_web_socket('**/*', lambda socket: socket.close())
                self.page = await self.context.new_page()
                await self.page.goto('about:blank')
                await self.page.evaluate('window.__codeState = {}')
            self.cells += 1
            try:
                result = await asyncio.wait_for(
                    self.page.evaluate(script, {'html': html, 'code': code}), CELL_SECONDS)
            except asyncio.TimeoutError:
                await self.close()
                raise ValueError(f'Code cell exceeded {CELL_SECONDS} seconds; workspace reset.')
            if not isinstance(result, str):
                raise ValueError('Code must return a result.')
            if len(result) > limit:
                raise ValueError(f'Code returned {len(result)} characters; limit is {limit}.')
            return result

    async def execute(self, html: str, code: str) -> str:
        try:
            return await self._run(html, code, CELL_JS, MAX_OUTPUT)
        except ValueError as error:
            return str(error)

    async def execute_json(self, html: str, code: str) -> str:
        """Return only the cell's JSON result for a typed output function."""
        return await self._run(html, code, CELL_JSON_JS, MAX_FINAL)

    async def close(self):
        if self.context is not None:
            try:
                await asyncio.wait_for(self.context.close(), 2)
            except Exception:
                pass
        self.context = self.page = None


async def selected_snapshot(session, ref: str) -> dict:
    """Read only the selected current element, preserving its visible text for grounding."""
    async def read():
        async with session.lock:
            await session.revive()
            element = session.page.locator('body') if ref == 'page' else await locate(session.page, ref)
            if element is None:
                raise ValueError(f'No element {ref} on this page; choose a ref from the current view.')
            return await element.evaluate(SNAPSHOT_JS)

    try:
        snapshot = await asyncio.wait_for(read(), SNAPSHOT_SECONDS)
    except asyncio.TimeoutError as error:
        raise ValueError(f'Selected page did not answer within {SNAPSHOT_SECONDS} seconds.') from error
    html = snapshot['html']
    if len(html) > MAX_SNAPSHOT:
        raise ValueError(f'Selected element is {len(html)} characters; choose a smaller ref.')
    session.seen += '\n' + snapshot['text']
    return snapshot


async def analyze_selected(ctx: RunContext[Deps], ref: str, code: str) -> str:
    """Run JavaScript on one model-selected page element; use ref='page' for the current page.

    In code, query the inert `doc` with DOM methods, use `state` to keep data for
    later cells, and `console.log(...)` or `return ...` for a short answer.
    This tool cannot click, navigate or inspect a different website.
    """
    session = ctx.deps.session
    try:
        snapshot = await selected_snapshot(session, ref)
    except ValueError as error:
        return str(error)
    html = snapshot['html']
    kernel = ctx.deps.code_kernel
    result = await kernel.execute(html, code)
    session.trace.event(session.name, 'code_cell', ref=ref, snapshot_chars=len(html),
                        code_chars=len(code), output_chars=len(result))
    if os.environ.get('AGENT_CODE_TRACE') == '1':
        session.trace.event(session.name, 'code_detail', quiet=True, ref=ref,
                            code=code[:MAX_CODE], result=result)
    return result or '(no output; use console.log or return)'


def finish_function(output_type, grounded: bool, context: str):
    """Build a typed output function for a worker's model-selected snapshot."""
    adapter = TypeAdapter(output_type)

    async def finish_from_code(ctx: RunContext[Deps], ref: str, code: str):
        """Run code on the selected snapshot and finish with its JSON result."""
        session = ctx.deps.session
        try:
            snapshot = await selected_snapshot(session, ref)
            raw = await ctx.deps.code_kernel.execute_json(snapshot['html'], code)
            result = adapter.validate_json(raw)
        except Exception as error:
            # A model-authored cell can fail for many reasons (including a JS exception).
            # Ask the model to fix the cell rather than ending the worker.
            raise ModelRetry(f'Code did not return the required JSON result: {str(error)[:500]}') from error
        if grounded:
            text = adapter.dump_json(result).decode()
            missing = unseen_values(text, session.seen + '\n' + context)
            if missing:
                raise ModelRetry(f"{', '.join(missing[:10])} appear on no selected page. "
                                 'Return only values copied from the selected page.')
        ctx.deps.code_kernel.finishes += 1
        session.trace.event(session.name, 'code_finish', ref=ref, snapshot_chars=len(snapshot['html']),
                            code_chars=len(code), output_chars=len(raw))
        if os.environ.get('AGENT_CODE_TRACE') == '1':
            session.trace.event(session.name, 'code_detail', quiet=True, ref=ref,
                                code=code[:MAX_CODE], result=raw)
        return result

    finish_from_code.__annotations__['return'] = output_type
    return finish_from_code


def enabled() -> bool:
    return os.environ.get('AGENT_CODE_KERNEL') == '1'

